USE [snabdrive_db];
GO

IF COL_LENGTH('dbo.RegistryItems', 'DeliveryTerms') IS NULL
BEGIN
    RAISERROR(N'Сначала выполните web/sql/updates_2026.sql — нет колонки DeliveryTerms.', 16, 1);
    SET NOEXEC ON;
END
